import sys
import threading


class ExprError(Exception):
    def __init__(self, kind, pos):
        super().__init__("%s error at position %d" % (kind, pos))
        self.kind = kind
        self.pos = pos


_TWO = {'||', '&&', '==', '!=', '<=', '>=', '**'}
_ONE = set('!<>+-*/%?:(),')
_ID_START = set('ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz_')
_ID_CHAR = _ID_START | set('0123456789')
_DIGITS = set('0123456789')
_WS = set(' \t\n\r')


def _to_int(s):
    # Avoid the int/str conversion digit limit of newer Python versions.
    if len(s) <= 1000:
        return int(s)
    k = len(s) // 2
    return _to_int(s[:-k]) * (10 ** k) + _to_int(s[-k:])


def _tokenize(src):
    toks = []
    i = 0
    n = len(src)
    while i < n:
        c = src[i]
        if c in _WS:
            i += 1
            continue
        if c in _DIGITS:
            j = i
            while j < n and src[j] in _DIGITS:
                j += 1
            if j - i >= 2 and c == '0':
                toks.append(('err', None, i))
                return toks
            toks.append(('num', _to_int(src[i:j]), i))
            i = j
            continue
        if c in _ID_START:
            j = i
            while j < n and src[j] in _ID_CHAR:
                j += 1
            w = src[i:j]
            if w == 'true':
                toks.append(('bool', True, i))
            elif w == 'false':
                toks.append(('bool', False, i))
            else:
                toks.append(('id', w, i))
            i = j
            continue
        two = src[i:i + 2]
        if two in _TWO:
            toks.append((two, None, i))
            i += 2
            continue
        if c in _ONE:
            toks.append((c, None, i))
            i += 1
            continue
        toks.append(('err', None, i))
        return toks
    toks.append(('eof', None, n))
    return toks


class _Parser:
    def __init__(self, toks):
        self.toks = toks
        self.i = 0

    def kind(self):
        return self.toks[self.i][0]

    def pos(self):
        return self.toks[self.i][2]

    def fail(self):
        raise ExprError('syntax', self.toks[self.i][2])

    def parse(self):
        node = self.expr()
        if self.kind() != 'eof':
            self.fail()
        return node

    def expr(self):
        items = []
        cond = self.or_()
        while self.kind() == '?':
            q = self.pos()
            self.i += 1
            a = self.expr()
            if self.kind() != ':':
                self.fail()
            self.i += 1
            items.append((cond, q, a))
            cond = self.or_()
        node = cond
        for c, q, a in reversed(items):
            node = ('tern', c, q, a, node)
        return node

    def or_(self):
        first = self.and_()
        rest = []
        while self.kind() == '||':
            p = self.pos()
            self.i += 1
            rest.append((p, self.and_()))
        return ('or', first, rest) if rest else first

    def and_(self):
        first = self.eq()
        rest = []
        while self.kind() == '&&':
            p = self.pos()
            self.i += 1
            rest.append((p, self.eq()))
        return ('and', first, rest) if rest else first

    def eq(self):
        left = self.rel()
        k = self.kind()
        if k == '==' or k == '!=':
            p = self.pos()
            self.i += 1
            right = self.rel()
            return ('cmp', k, p, left, right)
        return left

    def rel(self):
        left = self.add()
        k = self.kind()
        if k in ('<', '<=', '>', '>='):
            p = self.pos()
            self.i += 1
            right = self.add()
            return ('cmp', k, p, left, right)
        return left

    def add(self):
        first = self.mul()
        rest = []
        while True:
            k = self.kind()
            if k == '+' or k == '-':
                p = self.pos()
                self.i += 1
                rest.append((k, p, self.mul()))
            else:
                break
        return ('chain', first, rest) if rest else first

    def mul(self):
        first = self.unary()
        rest = []
        while True:
            k = self.kind()
            if k == '*' or k == '/' or k == '%':
                p = self.pos()
                self.i += 1
                rest.append((k, p, self.unary()))
            else:
                break
        return ('chain', first, rest) if rest else first

    def prefix_ops(self):
        ops = []
        while True:
            k = self.kind()
            if k == '-' or k == '!':
                ops.append((k, self.pos()))
                self.i += 1
            else:
                return ops

    def unary(self):
        ops = self.prefix_ops()
        node = self.power()
        return ('un', ops, node) if ops else node

    def power(self):
        prims = [self.primary()]
        stars = [None]
        unops = [None]
        while self.kind() == '**':
            stars.append(self.pos())
            self.i += 1
            unops.append(self.prefix_ops())
            prims.append(self.primary())
        if len(prims) == 1:
            return prims[0]
        return ('pow', prims, stars, unops)

    def primary(self):
        k, v, p = self.toks[self.i]
        if k == 'num':
            self.i += 1
            return ('int', v)
        if k == 'bool':
            self.i += 1
            return ('bool', v)
        if k == 'id':
            self.i += 1
            if self.kind() == '(':
                self.i += 1
                args = []
                if self.kind() != ')':
                    args.append(self.expr())
                    while self.kind() == ',':
                        self.i += 1
                        args.append(self.expr())
                if self.kind() != ')':
                    self.fail()
                self.i += 1
                return ('call', v, p, args)
            return ('var', v, p)
        if k == '(':
            self.i += 1
            e = self.expr()
            if self.kind() != ')':
                self.fail()
            self.i += 1
            return e
        self.fail()


def _is_int(v):
    return isinstance(v, int) and not isinstance(v, bool)


def _is_bool(v):
    return isinstance(v, bool)


def _apply_unary(ops, v):
    for op, p in reversed(ops):
        if op == '-':
            if not _is_int(v):
                raise ExprError('type', p)
            v = -v
        else:
            if not _is_bool(v):
                raise ExprError('type', p)
            v = not v
    return v


def _arith(op, a, b, p):
    if not (_is_int(a) and _is_int(b)):
        raise ExprError('type', p)
    if op == '+':
        return a + b
    if op == '-':
        return a - b
    if op == '*':
        return a * b
    if op == '/' or op == '%':
        if b == 0:
            raise ExprError('zero-division', p)
        q = abs(a) // abs(b)
        if (a < 0) != (b < 0):
            q = -q
        if op == '/':
            return q
        return a - b * q
    raise AssertionError(op)


def _pow(a, b, p):
    if not (_is_int(a) and _is_int(b)):
        raise ExprError('type', p)
    if b < 0 or b > 1000:
        raise ExprError('domain', p)
    return a ** b


def _compare(op, a, b, p):
    if op == '==' or op == '!=':
        if not ((_is_int(a) and _is_int(b)) or (_is_bool(a) and _is_bool(b))):
            raise ExprError('type', p)
        return (a == b) if op == '==' else (a != b)
    if not (_is_int(a) and _is_int(b)):
        raise ExprError('type', p)
    if op == '<':
        return a < b
    if op == '<=':
        return a <= b
    if op == '>':
        return a > b
    return a >= b


def _make_eval(env):
    def ev(node):
        while True:
            t = node[0]
            if t == 'int' or t == 'bool':
                return node[1]
            if t == 'var':
                name = node[1]
                if name not in env:
                    raise ExprError('name', node[2])
                return env[name]
            if t == 'tern':
                c = ev(node[1])
                if not _is_bool(c):
                    raise ExprError('type', node[2])
                node = node[3] if c else node[4]
                continue
            if t == 'chain':
                v = ev(node[1])
                for op, p, sub in node[2]:
                    r = ev(sub)
                    v = _arith(op, v, r, p)
                return v
            if t == 'cmp':
                a = ev(node[3])
                b = ev(node[4])
                return _compare(node[1], a, b, node[2])
            if t == 'and':
                v = ev(node[1])
                for p, sub in node[2]:
                    if not _is_bool(v):
                        raise ExprError('type', p)
                    if not v:
                        continue
                    v = ev(sub)
                    if not _is_bool(v):
                        raise ExprError('type', p)
                return v
            if t == 'or':
                v = ev(node[1])
                for p, sub in node[2]:
                    if not _is_bool(v):
                        raise ExprError('type', p)
                    if v:
                        continue
                    v = ev(sub)
                    if not _is_bool(v):
                        raise ExprError('type', p)
                return v
            if t == 'un':
                v = ev(node[2])
                return _apply_unary(node[1], v)
            if t == 'pow':
                prims, stars, unops = node[1], node[2], node[3]
                vals = [ev(x) for x in prims]
                acc = vals[-1]
                for i in range(len(prims) - 1, 0, -1):
                    if unops[i]:
                        acc = _apply_unary(unops[i], acc)
                    acc = _pow(vals[i - 1], acc, stars[i])
                return acc
            if t == 'call':
                name, p, args = node[1], node[2], node[3]
                if name not in ('min', 'max', 'abs'):
                    raise ExprError('name', p)
                if name == 'abs':
                    if len(args) != 1:
                        raise ExprError('arity', p)
                elif len(args) < 1:
                    raise ExprError('arity', p)
                vals = [ev(a) for a in args]
                for v in vals:
                    if not _is_int(v):
                        raise ExprError('type', p)
                if name == 'abs':
                    return abs(vals[0])
                if name == 'min':
                    return min(vals)
                return max(vals)
            raise AssertionError(t)
    return ev


def _evaluate(src, env):
    toks = _tokenize(src)
    tree = _Parser(toks).parse()
    return _make_eval(env)(tree)


_STACK_LOCK = threading.Lock()


def evaluate(src, env):
    if sys.getrecursionlimit() < 1000000:
        sys.setrecursionlimit(1000000)
    result = {}

    def run():
        try:
            result['v'] = _evaluate(src, env)
        except BaseException as e:  # propagate to caller
            result['e'] = e

    with _STACK_LOCK:
        old = threading.stack_size()
        try:
            try:
                threading.stack_size(512 * 1024 * 1024)
            except (ValueError, RuntimeError):
                try:
                    threading.stack_size(64 * 1024 * 1024)
                except (ValueError, RuntimeError):
                    pass
            t = threading.Thread(target=run)
            t.start()
        finally:
            threading.stack_size(old)
    t.join()
    if 'e' in result:
        raise result['e']
    return result['v']
